        NavigationStep.Action.TURN_LEFT -&gt; "Turn left"
        NavigationStep.Action.TURN_RIGHT -&gt; "Turn right"
        NavigationStep.Action.GO_STRAIGHT -&gt; "Continue straight"
        NavigationStep.Action.ARRIVE -&gt; "You have arrived"
