            ComponentCallbacks2.TRIM_MEMORY_UI_HIDDEN -&gt; {
                sceneView?.onPause()
            }
        }
    }

    override fun onDestroy() {
        // Nettoyer correctement
        sceneView?.onDestroy()
        sceneView = null
        super.onDestroy()
    }
